import type { ProcessHandle } from "../contracts.js";
import type { OptionValue } from "./define.js";
import type { CommandDecl, EndpointDecl, ModuleDecl, OptionDecl, ServiceDecl } from "./manifest-types.js";

export interface Pin {
  readonly sha256: string;
  readonly bytes: number;
}

/** A pinned file and the URL the application serves it from. */
export interface PinnedFile extends Pin {
  readonly url: string;
}

/** Everything `spawnModule` needs besides the manifest; generated by `oxidevm wasm stage`. */
export interface LaunchPins {
  /** Digest of the sorted `SHA256SUMS` lines; it names one immutable release. */
  readonly release: string;
  readonly adapter: PinnedFile;
  readonly artifacts: Readonly<Record<string, PinnedFile>>;
}

/** The consumer's view of an installed module: its manifest literal, so options and endpoints are typed. */
export interface ModuleHandle<M extends ModuleDecl = ModuleDecl> {
  readonly manifest: M;
  readonly pins: LaunchPins;
}

/** Builds a handle; the generated `src/oxidevm.modules.generated.ts` calls this once per module. */
export function moduleHandle<const M extends ModuleDecl>(manifest: M, pins: LaunchPins): ModuleHandle<M> {
  return { manifest, pins };
}

type RequiredOptionKeys<O> = { [K in keyof O]: O[K] extends { readonly default: unknown } ? never : K }[keyof O];

/** Options the consumer passes: those without a default are required. */
export type OptionArgs<O> = O extends Readonly<Record<string, OptionDecl>>
  ? { readonly [K in RequiredOptionKeys<O>]: OptionValue<O[K]> } & { readonly [K in Exclude<keyof O, RequiredOptionKeys<O>>]?: OptionValue<O[K]> }
  : never;

/** A manifest whose `id` is a plain `string` has lost its literal type (it was loaded, not generated), so nothing about it can be derived. */
type Erased<M extends ModuleDecl> = string extends M["id"] ? true : false;

type CommandOnly<M> = M extends CommandDecl
  ? { readonly args?: readonly string[]; readonly cwd?: string; readonly env?: Readonly<Record<string, string>> }
  : unknown;
type ExclusiveOnly<M> = M extends { readonly process: { readonly exclusive: "workspace" } } ? { readonly workspaceId: string } : unknown;
type OptionsField<M> = M extends { readonly options: infer O }
  ? Record<never, never> extends OptionArgs<O> ? { readonly options?: OptionArgs<O> } : { readonly options: OptionArgs<O> }
  : unknown;

/** Everything `spawnModule` may be given when the manifest's literal type is unknown; the runner validates it at run time. */
export interface ErasedSpawnOptions {
  readonly signal?: AbortSignal;
  readonly args?: readonly string[];
  readonly cwd?: string;
  readonly env?: Readonly<Record<string, string>>;
  readonly workspaceId?: string;
  readonly options?: Readonly<Record<string, unknown>>;
}

/** For a generated handle, exactly the options its manifest allows; for an erased one, all of them, optionally. */
export type SpawnOptions<M extends ModuleDecl> = Erased<M> extends true
  ? ErasedSpawnOptions
  : { readonly signal?: AbortSignal } & CommandOnly<M> & ExclusiveOnly<M> & OptionsField<M>;

/** The optional or required options argument of `spawnModule`, derived from the manifest. */
export type SpawnArgs<M extends ModuleDecl> = Record<never, never> extends SpawnOptions<M> ? [options?: SpawnOptions<M>] : [options: SpawnOptions<M>];

/**
 * A running module: the ordinary process handle, plus, for a service, its declared endpoints and the
 * `info` its adapter reported in the ready line.
 */
export type ModuleProcess<M extends ModuleDecl> = ProcessHandle & (Erased<M> extends true
  ? { readonly endpoints?: Readonly<Record<string, EndpointDecl>>; readonly info?: Readonly<Record<string, string | number | boolean>> }
  : M extends ServiceDecl ? { readonly endpoints: M["expose"]; readonly info: Readonly<Record<string, string | number | boolean>> } : unknown);
